def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_pressure = 0.0
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = prev.get('bid', 0.0)
                prev_bids.append(b)
                if b > opp_pressure:
                    opp_pressure = b

    if not alive_opponents:
        return max(0.0, min(budget, 18.0))

    scarcity = supply / float(WATER_REQ)
    severe_scarcity = scarcity < 1.35

    danger = 0
    if hp <= 3:
        danger += 2
    elif hp <= 5:
        danger += 1
    if no_water_days >= 2:
        danger += 2
    elif no_water_days >= 1:
        danger += 1
    if day >= 8:
        danger += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / float(len(prev_bids)) if prev_bids else 0.0

    if severe_scarcity:
        if danger >= 3:
            target = max(92.0, highest_prev + 3.0)
        elif danger >= 2:
            target = max(72.0, avg_prev + 2.0)
        else:
            if highest_prev >= 110.0:
                target = 8.0
            elif highest_prev >= 85.0:
                target = 18.0
            else:
                target = 32.0
    else:
        if danger >= 3:
            target = max(78.0, highest_prev + 2.0)
        elif danger >= 2:
            target = max(58.0, avg_prev + 1.5)
        else:
            target = 24.0 if highest_prev >= 80.0 else 38.0

    for oid, opp in opponents_status.items():
        if not opp.get('alive'):
            continue
        prev = opp.get('previous_trace', {})
        if not prev:
            continue
        obid = prev.get('bid', 0.0)
        ohp = opp.get('hp', 10)
        onwd = opp.get('no_water_days', 0)
        if ohp <= 3 or onwd >= 2:
            if obid > 0:
                target = max(target, obid + 1.0)

    if budget < 25:
        target = min(target, budget)
    elif budget < 60 and danger < 3:
        target = min(target, 35.0)

    min_keep = 0.0
    if day < 9:
        min_keep = 12.0
    bid = min(budget - min_keep, target)
    if danger >= 3:
        bid = min(budget, max(bid, 65.0))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    remaining_days = EPISODE_DAYS - day_context['day'] + 1

    # If HP is critical, bid aggressively
    if my_status['hp'] <= 3:
        if remaining_days <= 2:
            return min(my_status['budget'], DAILY_SALARY * 0.99)
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    # If HP is good, react to opponents' previous bids
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If opponents are bidding very high
        if highest_prev_bid >= DAILY_SALARY * 0.9:
            # If my HP is good and many days left, consider saving budget
            if my_status['hp'] > 5 and remaining_days > 2:
                return min(my_status['budget'], DAILY_SALARY * 0.7)
            else:
                # HP is good but not excellent, or it's getting late, so compete
                return min(my_status['budget'], highest_prev_bid + 2.0)

        # If opponents are bidding moderately high
        elif highest_prev_bid >= DAILY_SALARY * 0.7:
            return min(my_status['budget'], highest_prev_bid + 1.0)

        # If opponents are bidding low
        else:
            # If my HP is good, bid reasonably above their low bid
            return min(my_status['budget'], max(DAILY_SALARY * 0.6, highest_prev_bid + 5.0))

    # Initial days or if no previous bids from alive opponents
    if my_status['hp'] <= 5:
        return min(my_status['budget'], DAILY_SALARY * 0.75)
    else:
        return min(my_status['budget'], DAILY_SALARY * 0.6)
